INSERT INTO `sma_contact_form` VALUES (1,'Joseph','C','Free SEO Audit',NULL,'2025-07-10 09:47:02'),(2,'Kimberley','Sigel','Hello laptopexpert.lk Owner.','Salutare. Mai sunteti interesati de o locatie pentru eveniment?\r\nS-a eliberat un loc la Loockyano Ballroom.\r\nvezi poze pe loockyano.ro si daca iti place locatia, rezerva repede, pana nu se ocupa locul.','2025-07-27 12:00:33'),(3,'Dyan','Loving','Despre noul Angajat','Bun? ziua. Revin la dumneavoastr? cu informa?ii bomb?!\r\nDac? îmi acorda?i un minut, v? voi schimba via?a.\r\n\r\nIdeea este simpl?:\r\nA?i vrea s? ave?i un \\\"angajat\\\" (c?ruia s? nu îi pl?ti?i salariu) care st? non-stop pe site-ul dumneavoastr?, monitorizeaz? traficul ?i abordeaz? vizitatorii, pentru a-i convinge ?i ajuta s? cumpere produsele/serviciile dumneavoastr??\r\nDar dac? acela?i angajat ar ?i oferi suport ?i informa?ii clien?ilor care au cump?rat deja? Sau celor care doar se informeaz??\r\n?i dac? are capacitatea s? vorbeasc? ?i cu to?i deodat??\r\n\r\nNu sun? super ideal?\r\nCÂT COST?? Doar 50 de euro pe lun?! dac? folosi?i\r\n?i îl pute?i achizi?iona direct de pe verobots.ro\r\n\r\nPentru doar 50 de euro pe lun?, ave?i un angajat minune, care înva?? el singur totul despre afacerea dumneavoastr? ?i ulterior îl pute?i educa cum vre?i, în timp real.\r\nDureaz? doar 5 minute s? îl implementa?i, f?r? s? necesite cuno?tin?e tehnice.\r\n\r\n\r\nNu dori?i s? v? acorda?i o ?ans? ?i s? încerca?i acest agent virtual? Nu pierde?i nimic! Dimpotriv?, chiar de mâine ve?i observa cum v? cresc vânz?rile ?i ve?i sim?i cum v? elibera?i timpul.\r\nAgentul poate mai multe, inclusiv v? ofer? un raport pentru fiecare conversa?ie, ca s? ?ti?i ce a vorbit cu fiecare persoan?, \r\n\r\nIntra?i pe verobots.ro ?i juca?i-v? cu acest agent, o s? îmi mul?umi?i pentru el, dup? ce îl ve?i vedea cât este de util.\r\n','2026-02-01 10:35:05'),(4,'Ezra','Nangle','Am clienti pentru dumneavoastra. ii vreti?','Buna ziua. Stiu cum sa cresteti numarul de clienti in doar cateva zile, FARA BANI!\r\nNu trebuie sa platiti niciun ban nimanui!\r\nNu trebuie sa faceti nimic complicat!\r\n\r\nDoar 10 minute trebuie sa alocati si va promit ca ceea ce va ofer este solutia pe care o cautati de foarte mult timp.\r\n\r\n\r\nCE TREBUIE SA FACETI?\r\nGRATUIT! SI DUREAZA DOAR 10 MINUTE, Trebuie sa va creati/inregistrati un A.I. de la VeroBots.\r\nAcest AI sta pe site-ul dumneavoastra (exact cum stau anumite persoane in magazine) si intreaba clientii daca au nevoie de ajutor sa inteleaga anumite produse, sa aleaga produsul corect... etc.\r\nDA! Acest AI abordeaza el vizitatorii site-ului. \r\n\r\nCum il creati?\r\n- intrati pe verobots.net si apasati pe \\\"INREGISTRARE GRATUITA\\\". \r\n- Va cere o adresa de e-mail, numele si o parola pentru a creea contul.\r\n- intrati automat in cont si apasati pe \\\"Activeaz? Demo Gratuit\\\"\r\n- Acolo trebuie sa dati un nume agentului si sa introduceti site-ul dumneavoastra. (are 3 campuri de completat, cititi detaliile, sunt putine).\r\n- Dupa ce ati confirmat domeniul, apasati pe \\\"Creeaza widget\\\" de la pasul 3, ca sa configurati textele si culorile agentului AI, asa cum va place.\r\n- Obtineti codul widgetului si il introduceti pe site.\r\n\r\n\r\nASTA ESTE TOT CE TREBUIE SA FACETI!\r\nDureaza maxim 10 minute cu totul! \r\nmai mult, cand va logati in cont, aveti si un video, care sa va ajute.\r\n\r\nTimp de 7 zile, 100% gratuit, acel agent va sta pe site-ul dumneavoastra, va vorbi cu vizitatorii si ii va convinge sa cumpere de la dumneavoastra.\r\n- AVETI POSIBILITATE ASA VEDETI CONVERSATIILE. In cont, aveti o sectiune de mesagerie, unde primiti un raport cu fiecare conversatie pe care o are agentul cu vizitatorii site-ului.\r\nFoarte util sa vedeti ce au nevoie clientii.\r\n\r\n\r\nIn aceste 7 zile, AI-ul asta o sa va aduca suficienti bani incat sa considerati ca merita sa platiti 50 de euro pe luna pentru el.\r\nDupa 7 zile, il platiti din profitul pe care il genereaza acest AI! Deci, beneficiati de el 100% gratis.\r\n\r\nCe va puteti dori mai mult decat sa va dublati, sau chiar triplati numarul de clienti, cu doar 10 zile de munca?\r\nFara promisiuni desarte, fara sa platiti si sa asteptati rezultate cu lunile, fara sa asteptati dupa IT-isti cu lunile sa va faca ceva.\r\npur si simplu, obtineti dumneavoastra codul de acolo, il introduceti pe site si gata. Ati dublat vanzarile.\r\n\r\nCe motive ati avea sa nu doriti asa ceva? GRATIS, INSTANT, EFICIENT...\r\nSi da, Agentul are mult mai multe optiuni, inclusiv puteti edita instructiunile si datele in timp real! Il invatati dumneavoastra ce vreti si cand vreti.\r\nSi nu! Nu mai platiti nimic pe langa agent, doar 50 de euro pe luna.\r\n\r\nNu va mai scriu mai multe, pentru ca deja mesajul este prea lung, insa va asigur ca veti regreta daca nu veti aloca aceste 10 minute ca sa va cresteti afacerea acum.\r\ncand o vor face toti, deja veti fi in dezavantaj!\r\n','2026-02-02 01:20:55'),(5,'Toma','Laurentiu','Parteneriat win-win: pl?ti?i doar din profit','Bun? ziua,\r\n\r\nAm identificat clien?i interesa?i s? pl?teasc? pentru ceea ce face?i; dori?i s? vi-i trimit?\r\n\r\nDe?in o metod? prin care pot asigura un num?r constant de solicit?ri ?i comenzi pentru afacerea dvs.\r\n\r\nA?i fi interesat s? îmi oferi?i un bonus de performan?? din profitul pe care îl generez pentru dvs.?\r\n\r\nNu v? cer niciun ban înainte ?i nu trebuie s? face?i absolut nimic.\r\n\r\nEu aduc clien?ii prin laptopexpert.lk, dumneavoastr? încasa?i, apoi îmi acorda?i partea stabilit?.\r\n\r\nActivitatea este complet legal? ?i transparent?, f?r? complica?ii.\r\n\r\nA?tept r?spunsul dvs. ca s? v? prezint planul complet.\r\n\r\nV? spun totul în urm?torul e-mail; acum am vrut doar s? verific dac? sunte?i interesat.\r\n\r\nPot lucra doar cu 2-3 firme pe aceast? ni??. V? rog s? îmi r?spunde?i în maximum o s?pt?mân? dac? sunte?i interesat.\r\n\r\nV? mul?umesc anticipat ?i a?tept un semn.\r\n\r\nAugustin.\r\n','2026-02-07 13:05:36'),(6,'Marton','Georgeta','Clien?i noi pentru site – f?r? avans','Buna ziua. Absolut gratuit, puteti obtine urmatoarele chiar de azi, dar nu mai tarziu de 15 Martie:\r\nTrebuie doar sa vreti. Nu trebuie sa faceti nimic complex. Ba chiar mai mult de atat, facem noi totul pentru dumneavoastra daca vreti.\r\n\r\n- Acces la o baza de date cu peste 4 milioane de clienti din europa, care (peste 600.000 din Romania), care obisnuiesc sa plaseze comenzi false, sa faca programari false, sa comande si sa refuze livrarea\r\nau care fac scandaluri, reclamatii, amenintari, cu scopul de a obtine produse sau servicii gratis.\r\n\r\n- Un creier virtual, care invata singur despre produsele/serviciile dumneavoastra si care este conectat la un Agent Virtual, care sta pe site-ul dumneavoastra si abordeaza vizitatorii, pentru a-i convinge sa cumpere ce vindeti dumneavoastra.\r\nAcest agent va creste semnificativ vanzarile.\r\n\r\n- O aplicatie pe care vizitatorii/clientii site-ului dumneavoastra, o pot instala cu un singur click pe telefonul sau laptopul lor, pentru a va putea accesa mai rapid.\r\nAcest lucru va ajuta ca acesti clienti sa nu mai ajunga pe google, expusi reclamelor competitorilor.\r\nLucru care pe termen lung, poate creste rata de retentie a clientilor si de 10 ori.\r\n\r\n\r\nDA! toate acestea GRATIS!\r\nVa inregistrati inainte de 15 Martie prin site-ul agenticlogic.shop si timp de doua saptamani, folositi toate aceste 3 sisteme GRATIS, fara nicio obligatie!\r\n\r\nNu platiti nimic in avans, nu inregistrati carduri de credit. Doar va bucurati de ele.\r\nDupa ce v-ati convins ca aceste sisteme va aduc mii de euro in plus lunar si va reduc pierderi de sute sau mii de euro, platiti doar 50 de euro pe luna.\r\nExact! Doar 50 de euro pe luna, bani pe care ii platiti din profitul pe care vi-l genereaza aceste sisteme.\r\n\r\nDureaza doar 10 minute sa le implementati si daca nu va descurcati, dupa ce v-ati inregistrat, ne puteti contacta prin whatsapp si va ajutam noi.\r\nNu aveti nevoie de cunostinte tehnice. Facem noi tot ce trebuie, ca sa va aducem bani lunar, bani din care sa ne platiti si noua doar 50 de euro pe luna.\r\n\r\nla asa oferta, chiar ca nu aveti nicio scuza sa spuneti \\\"nu\\\".','2026-03-10 06:02:57'),(7,'Manole','Manole','Avem Cereri de la Clien?i pentru Domeniul Dumneavoastr?','Buna ziua. As putea sa va aduc un numar foarte mare de clienti intr-un timp foarte scurt!\r\nCateva sute, sau poate chiar mii de clienti, de obicei in decurs de 1-2 saptamani.\r\nV-ar interesa?\r\n\r\nDaca da, va spun aici direct cum procedez, iar daca sunteti interesati, am o super oferta pentru dumneavoastra daca dati curs ofertei mele saptamana aceasta.\r\n\r\nCE FAC MAI EXACT?\r\nAsa cum v-am contactat pe dumneavoastra, prin formularul de contact al site-ului dumneavoastra, asa pot contacta zeci de mii de firme, intre 50.000 si 70.000 de firme.\r\n\r\nDaca mesajul si produsele/serviciile dumneavoastra se nimeresc sa fie de interest pentru persoanele care citesc acele e-mailuri, sau pentru firmele reprezentate de acele persoane, veti avea un numar mai mare sau mai mic de clienti, intr-un timp relativ scurt.\r\n(De obicei devin clienti si persoanele fizice si firmele.)\r\n\r\nNu este nimic complicat, eu ma ocup de tot si va trimit la sfarsit si un raport.\r\n\r\nOFERTA MEA:\r\n- Pentru ca vine pastele, vreau sa va ofer acest serviciu de 5 ori mai ieftin decat incasez de obicei\r\n- Adica, doar 1000 de lei + TVA. (platibili o singura data)\r\n\r\n- Puteti beneficia de aceasta oferta, daca dati curs ofertei saptamana aceasta si daca imi platiti inainte de 8 Aprilie.\r\n- Serviciile le pot presta oricand. Fie acum inainte de paste, fie dupa paste, in functie de cum va avantajeaza pe dumneavoastra mai mult.\r\n\r\nSCOPUL OFERTEI\r\n- Scopul acestei oferte, este sa va largesc orizonturile, si sa vedeti cat de profitabila poate fi o astfel de campanie, ca sa ne gandim la o colaborare pe termen lung, pentru mai multe tipuri de servicii similare.\r\n\r\nSUNTETI INTERESATI?\r\nTot ce trebuie sa faceti este sa imi dati reply la acest e-mail si sa imi spuneti cand ati fi interesati de o astfel de campanie.\r\n\r\n- Pentru toate serviciile se ofera factura cu TVA deductibil.\r\nVa multumesc si astept sa va arat cat de profitabil pot fi pentru dumneavoastra','2026-04-02 11:22:34'),(8,'Fiodor','Fiodor','Am Solicit?ri de la Clien?i ?i M? Gândesc la Dumneavoastr?','Bun? ziua,\r\n\r\nAm identificat în zona dumneavoastr? mai multe firme care ar putea fi interesate de serviciile/produsele dumneavoastr?. Practic, clien?i poten?iali pe care poate nu i-a?i luat în calcul pân? acum.\r\n\r\nCe v? pun la dispozi?ie, pentru doar cateva sute de lei:\r\nO extragere din Google Maps a tuturor firmelor din aria dumneavoastr? (cu telefon, email, site, adres?), sortate pe categorii de activitate. Datele sunt livrate într-un fi?ier pe care îl p?stra?i ?i îl pute?i folosi oricând.\r\n\r\nCe pute?i face cu aceste date:\r\nContacta?i direct firmele (prin email, telefon, SMS, WhatsApp), sau prin formularul de contact, a?a cum v-am contactat eu.\r\nSau le pot contacta eu pentru dumneavoastr?.\r\n\r\nCa s? v? conving de valoarea informa?iilor, v? ofer gratuit câteva unelte pentru a începe:\r\n\r\nscripturi de contact prin formular\r\nsoft de trimitere e-mailuri\r\nsoft de contactare prin WhatsApp\r\nop?ional: soft de trimis SMS-uri sau de apeluri telefonice cu AI\r\n\r\nDac? v? place ideea, îmi pute?i scrie pe WhatsApp la 0766-465-311 ?i putem continua discu?ia.\r\nMul?umesc pentru timpul acordat.','2026-04-30 08:46:14');
