L,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'lenovo-side-bag',NULL,NULL,NULL,0.0000,NULL,1,0,'',0,0,'0000-00-00 00:00:00'),(8,'POUCH001','LAPTOP POUCH 14 INCH',1,450.0000,950.0000,0.0000,'f5c5aef010a229075e7d1471dbab2cd3.jpeg',73,NULL,'','','','','','',2.0000,NULL,1,'',NULL,'code25',NULL,'',NULL,'standard',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'laptop-pouch-14-inch',NULL,NULL,NULL,0.0000,NULL,1,0,'',0,0,'0000-00-00 00:00:00'),(9,'POUCH002','LAPTOP POUCH 15.6 INCH',1,450.0000,950.0000,0.0000,'12de97d0b2d045d7548006bb2399a7c1.jpeg',73,NULL,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'',NULL,'standard',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'laptop-pouch-156-inch',NULL,NULL,NULL,0.0000,NULL,4,0,'',0,0,'0000-00-00 00:00:00'),(10,'OTH002','TRANSPARENT 14 INCH KEYBOARD SKIN',1,70.0000,400.0000,0.0000,'7594c434c856fe02b0bde9c3840698ba.jpeg',56,NULL,'','','','','','',29.0000,NULL,1,'',NULL,'code25',NULL,'',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'transparent-14-inch-keyboard-skin',NULL,NULL,NULL,0.0000,NULL,3,0,'',0,0,'0000-00-00 00:00:00'),(11,'KEBD002','TRANSPARENT 15.6 INCH KEYBOARD SKIN',1,70.0000,400.0000,0.0000,'d7dfa62bf0e4498c9168b0bfbab09257.jpeg',56,NULL,'','','','','','',14.0000,NULL,1,'',NULL,'code25',NULL,'',NULL,'standard',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'transparent-156-inch-keyboard-skin',NULL,NULL,NULL,0.0000,NULL,2,0,'',0,0,'0000-00-00 00:00:00'),(12,'VIRUS001','KASPERSKY SECURITY 01 DEVICE',1,1800.0000,2500.0000,0.0000,'08bd5c5cf2ec27306f2f7bf3d7ab7c06.jpeg',71,NULL,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>Kaspersky Security for one device typically covers a single Windows, macOS, Android, or iOS device. The specific requirements vary depending on the operating system, but generally include <mark>sufficient RAM (2GB for Windows and macOS) and disk space (1.5GB or more), along with an active internet connection for installation and updates</mark>.</p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div>\r\n<p>Detailed Specifications:</p><ul><li><div><div><div><div><strong>Operating System Compatibility:</strong><ul><li><strong>Windows:</strong> Windows 11, 10, 8.1, 7 (with latest updates). <div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></li>\r\n<li><strong>macOS:</strong> Latest supported versions. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li>\r\n<li><strong>Android:</strong> Android 8.0 and later. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li>\r\n<li><strong>iOS:</strong> Limited features available. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li></ul></div></div></div></div></li>\r\n<li><div><strong>Hardware Requirements:</strong><ul><li><strong>Windows/macOS:</strong><ul><li>Minimum 2GB RAM. <div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></li>\r\n<li>Minimum 1.5GB free disk space. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li>\r\n<li>Processor that supports SSE2 instructions. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li></ul></li>\r\n<li><strong>Android:</strong> Requires an active internet connection. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li>\r\n<li><strong>iOS:</strong> Basic protection with limited features, requiring iPhone 6S or later, or iPad Air 2 or later. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li></ul></div></li></ul></div></div>\r\n<li><div><strong>Other Requirements:</strong><ul><li>Internet connection for installation, activation, and database updates. <div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></li><li>A My Kaspersky account is typically required for managing the subscription.</li></ul></div></li>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'kaspersky-security-01-device',NULL,NULL,NULL,0.0000,NULL,23,0,'',0,0,'0000-00-00 00:00:00'),(13,'COLPD001','MEETION CP2020 COOLING PAD',1,1800.0000,3500.0000,0.0000,'8fd13d6984cfb128116cf62d9583ce88.png',54,NULL,'','','','','','',2.0000,NULL,1,'',NULL,'code25',NULL,'<p>06 MONTHS WARRANTY</p><ul>\r\n<li><strong>Model:</strong> CP2020</li><li><strong>Dimensions:</strong> 34026532mm</li><li><strong>Weight:</strong> 440±5g</li><li><strong>Power:</strong> 4W</li><li><strong>Voltage and Current:</strong> 5V-≤800mA</li><li><strong>Interface:</strong> USB x 2</li><li><strong>Cable Length:</strong> 60±2cm</li><li><strong>Adjustable Angle:</strong> 15 degrees</li><li><strong>Compatibility:</strong> 9-14 inch laptops</li></ul>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,77,'meetion-cp2020-cooling-pad',NULL,NULL,NULL,0.0000,NULL,5,0,'',0,0,'0000-00-00 00:00:00'),(14,'COLPD002','MEETION CP4040 COOLING PAD',1,4600.0000,6000.0000,0.0000,'7eb6201d913879db808cf5fe6674ebf0.png',54,NULL,'','','','','','',3.0000,NULL,1,'',NULL,'code25',NULL,'<p>06 MONTHS WARRANTY</p><p>Key Features:</p><ul><li><strong>Model:</strong> CP4040</li><li><strong>Color:</strong> Black</li><li><strong>Dimensions:</strong> 370 × 265 × 32 mm</li><li><strong>Weight:</strong> 740 ± 5 g</li><li><strong>Power Consumption:</strong> 4W-5W</li><li><strong>Voltage & Current:</strong> 5V ≤ 1000mA</li><li><strong>USB Ports:</strong> 2</li><li><strong>Cable Length:</strong> 60 ± 2 cm</li><li><strong>Compatibility:</strong> 9-17 inch laptops</li><li><strong>Adjustable Angle:</strong> 6.5° - 45° <div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></li></ul><div>\r\n<div>Additional Details:<ul>\r\n<li><strong>Cooling Performance:</strong> The CP4040 is designed to efficiently dissipate heat from laptops, preventing overheating.</li><li><strong>USB Compatibility:</strong> It\\\'s designed to work with high-power USB ports.</li><li><strong>Ergonomics:</strong> The adjustable angle allows for comfortable viewing and typing.</li><li><strong>Portability:</strong> Its sleek design and dimensions make it portable.</li></ul></div></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,77,'meetion-cp4040-cooling-pad',NULL,NULL,NULL,0.0000,NULL,1,0,'',0,0,'0000-00-00 00:00:00'),(15,'COLPD010','MEETION CP5050 COOLING PAD',1,5300.0000,6500.0000,0.0000,'53521ef7f99095ff89eb3d44fcddf5cf.png',54,NULL,'','','','','','',3.0000,NULL,1,'',NULL,'code25',NULL,'<p>06 MONTHS WARRANTY</p><p>The MEETION CP5050 is a cooling pad designed for laptops, particularly for gaming. It features a <mark>5W fan, adjustable height (6.5-45 degrees), and dual USB ports</mark>. The dimensions are 40028836mm, and it weighs 1150±5g. </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div>\r\n<p>Here\\\'s a more detailed breakdown of the specs: </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div><ul>\r\n<li><strong>Model:</strong> CP5050</li><li><strong>Power:</strong> 5W</li><li><strong>Voltage/Current:</strong> 5V-≤1000mA</li><li><strong>Dimensions:</strong> 40028836mm</li><li><strong>Weight:</strong> 1150±5g</li><li><strong>Operable Angle:</strong> 6.5-45 degrees</li><li><strong>Features:</strong>\r\n<ul>\r\n<li>Dual USB ports for power and device connectivity</li><li>Adjustable height in 5 levels</li><li>Front anti-slip baffle for stability</li><li>Aluminum alloy panel for better heat dissipation</li><li>Customizable lighting and wind speed</li><li>Compatible with laptops up to 19 inches</li></ul></li><li><strong>Purpose:</strong> Designed for gaming laptops to prevent overheating and improve performance.</li></ul></div></div></div></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,77,'meetion-cp5050-cooling-pad',NULL,NULL,NULL,0.0000,NULL,47,0,'',0,0,'0000-00-00 00:00:00'),(16,'CBL001','LAPTOP CHARGER ORIGINAL POWER CABLE (3PIN)',1,375.0000,800.0000,0.0000,'f13d45ca098495a7f323aca3680461e7.png',69,NULL,'','','','','','',87.0000,NULL,1,'',NULL,'code25',NULL,'',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'laptop-charger-original-power-cable',NULL,NULL,NULL,0.0000,NULL,6,0,'',0,0,'0000-00-00 00:00:00'),(17,'KEBD001','JEDEL K13 OFFICE KAYBOARD',1,500.0000,1000.0000,0.0000,'d6e827d02e3d47ae677e0382f213d217.png',79,NULL,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>06 MONTHS WARRANTY</p><p>The JEDEL K13 is a wired, USB-connected office keyboard. It\\\'s designed for both office and home use, featuring a full-sized layout with <mark>104 keys and a spill-resistant design</mark>. It supports multiple languages including Sinhala, Tamil, and English.</p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div>\r\n<p>Here\\\'s a more detailed breakdown of its specifications: </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div><ul>\r\n<li><strong>Type:</strong> Wired USB keyboard.</li><li><strong>Connectivity:</strong> USB.</li><li><strong>Key Type:</strong> Membrane.</li><li><strong>Key Layout:</strong> Full-sized, 104 keys.</li><li><strong>Cable Length:</strong> 1.35 meters.</li><li><strong>Key Lifetime:</strong> 3 million key presses.</li><li><strong>Spill-Resistant:</strong> Yes.</li><li><strong>Language Support:</strong> Sinhala, Tamil, English.</li><li><strong>Color:</strong> Black.</li><li><strong>Size:</strong> 445 x 140 x 30 mm.</li><li><strong>Operating Voltage:</strong> 4.5-5V.</li><li><strong>Working Current:</strong> 70-100mA.</li><li><strong>Chip:</strong> 83063.</li><li><strong>Compatibility:</strong> Windows 7, Windows 8, Windows 10.</li></ul></div></div></div></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,71,'jedel-k13-office-kayboard',NULL,NULL,NULL,0.0000,NULL,7,0,'',0,0,'0000-00-00 00:00:00'),(18,'MOU001','MEETION R545 WIRELESS MOUSE',1,700.0000,1300.0000,0.0000,'769525fbd39bbc1833e0f9c32743bf85.jpeg',77,NULL,'','','','','','',0.0000,NULL,1,'',NULL,'code25',NULL,'<p>06 MONTHS WARRANTY</p><p>The MEETION R545 wireless mouse is a <mark>2.4GHz wireless optical mouse</mark> with a compact, ergonomic design. It offers a resolution of 1600 DPI, uses a single AA battery, and connects via a USB nano receiver. It has a wireless range of up to 10 meters and features an auto-sleep function for battery saving. The mouse is designed for everyday use and is compatible with Windows and Mac operating systems. </p>\r\n<div><div><div>&lt;svg&gt;&lt;/svg&gt;</div><p>Here\\\'s a more detailed breakdown of its specifications:</p>\r\n<div><div><div>&lt;svg&gt;&lt;/svg&gt;</div><div>Key Features:<ul>\r\n<li><strong>2.4GHz Wireless Connectivity:</strong> Provides a stable connection with a range of up to 10 meters.</li><li><strong>1600 DPI Resolution:</strong> Ensures precise cursor control.</li><li><strong>Ergonomic Design:</strong> Offers a comfortable grip to reduce hand fatigue.</li><li><strong>Auto Sleep Function:</strong> Automatically enters sleep mode to conserve battery life.</li><li><strong>Plug and Play:</strong> No additional software required.</li><li><strong>Compact and Lightweight:</strong> Dimensions are 100 x 60 x 39 mm, and it weighs around 70±5g.</li><li><strong>Power Source:</strong> Uses a single AA battery.</li><li><strong>Compatibility:</strong> Compatible with Windows XP/Vista/7/8/10 and Mac OS.</li><li><strong>Connectivity:</strong> Uses a USB nano receiver for connection.</li></ul></div></div></div></div></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,77,'meetion-r545-wireless-mouse',NULL,NULL,NULL,0.0000,NULL,7,0,'',0,0,'0000-00-00 00:00:00'),(20,'PHDD001','SEAGATE EXPANSION 1TB EXTERNAL HDD',1,16000.0000,19500.0000,0.0000,'no_image.png',65,NULL,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>03 YEAR WARRANTY</p><div>\r\n<div>Key Features:<ul>\r\n<li><strong>Storage Capacity:</strong> 1TB</li><li><strong>Interface:</strong> USB 3.0</li><li><strong>Compatibility:</strong> Windows and Mac</li><li><strong>Form Factor:</strong> 2.5-inch</li><li><strong>Dimensions:</strong> 4.6 x 3.1 x 0.5 inches (11.7 x 7.9 x 1.4 cm)</li><li><strong>Weight:</strong> 0.3 lb (0.1 kg)</li><li><strong>Power Source:</strong> USB bus power</li></ul></div></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,51,'seagate-expansion-1tb-external-hdd',NULL,NULL,NULL,0.0000,NULL,3,0,'',0,0,'0000-00-00 00:00:00'),(21,'PHDD002','TOSHIBA CANVIO BASICS 4TB EXTERNAL HDD',1,31000.0000,36000.0000,0.0000,'no_image.png',65,NULL,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><ul>\r\n<li><strong>Capacity:</strong> 4 TB.</li><li><strong>Form Factor:</strong> 2.5-inch.</li><li><strong>Interface:</strong> USB 3.2 Gen 1 (compatible with USB 2.0).</li><li><strong>Transfer Rate:</strong> ~5.0 Gbit/s.</li><li><strong>Power:</strong> USB bus power (max. 900 mA).</li><li><strong>Dimensions:</strong> 78 x 109 x 19.5 mm.</li><li><strong>Operating System:</strong> Windows (requires reformatting for Mac OS).</li><li><strong>Included Components:</strong> USB 3.0 cable (also works with USB 2.0), 1-year limited warranty, quick start guide.</li><li><strong>Read Speed:</strong> 5 Gigabytes per second.</li><li><strong>File System:</strong> NTFS (for Windows), requires reformatting for Mac OS.</li><li><strong>Rotational Speed:</strong> 5400 RPM.</li></ul>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,52,'toshiba-canvio-basics-4tb-external-hdd',NULL,NULL,NULL,0.0000,NULL,7,0,'',0,0,'0000-00-00 00:00:00'),(22,'PHDD005','TRANSCEND STOREJET 25H3 4TB USB 3.1 GEN 1 PORTABLE HDD',1,35800.0000,41500.0000,0.0000,'no_image.png',65,NULL,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><div>\r\n<div>Key Specifications:<ul>\r\n<li><strong>Interface:</strong> USB 3.1 Gen 1 (micro USB to USB Type A)</li><li><strong>Capacity:</strong> 4TB</li><li><strong>Drive Type:</strong> 2.5\\\" HDD</li><li><strong>Dimensions:</strong> 131.8 mm x 80.8 mm x 24.5 mm</li><li><strong>Weight:</strong> 298 g (10.51 oz)</li><li><strong>Operating Temperature:</strong> 5°C (41°F) ~ 55°C (131°F)</li><li><strong>Operating Voltage:</strong> 5V</li><li><strong>Shock Protection:</strong> Three-stage system meeting US military drop-test standards</li><li><strong>One-Touch Backup:</strong> Included with Transcend Elite software</li><li><strong>Operating Systems:</strong> Windows 7, 8, 10, Mac OS X 10.7 or later, Linux Kernel 2.6.31 or later</li></ul></div></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,22,'transcend-storejet-25h3-4tb-usb-31-gen-1-portable-hdd',NULL,NULL,NULL,0.0000,NULL,6,0,'',0,0,'0000-00-00 00:00:00'),(23,'OTH007','WD HARD DRIVE POUCH',1,450.0000,900.0000,0.0000,'ebe1ed081fb77c445af340c2896ca911.jpeg',73,NULL,'','','','','','',3.0000,NULL,1,'',NULL,'code25',NULL,'<p>WD (Western Digital) hard drive pouches, also known as cases or covers, are designed to protect portable hard drives from damage and keep them organized. These pouches typically have features like <mark>shock absorption, water resistance, and additional storage compartments for accessories like USB cables and memory cards</mark>.</p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div>\r\n<p>Here\\\'s a more detailed look at common specifications:</p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div>\r\n<p>Dimensions and Compatibility:</p><ul><li><div><div><div><div><strong>Size:</strong><p>Pouch dimensions vary, but common sizes include 6\\\" x 4.4\\\" x 1.2\\\" or 4\\\" x 1.5\\\" x 5\\\". </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></div></div></div></div></li>\r\n<li><div><strong>Compatibility:</strong><p>They are designed to fit various WD portable hard drives, including My Passport and Elements models. Many also fit other 2.5\\\" hard drives from different brands like Seagate, Toshiba, and Sony. </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></div></li>\r\n<li><div><strong>Interior Dimensions:</strong><p>These pouches often have specific interior dimensions to accommodate the hard drive snugly, with extra space for accessories. </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></div></li></ul></div>\r\n<p>Features and Protection:</p><ul><li><div><div><div><div><strong>Material:</strong><p>Common materials include leather, nylon, or a combination of hard shell and soft lining. </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></div></div></div></div></li>\r\n<li><div><strong>Shock Absorption:</strong><p>They may incorporate shock-absorbing foam or other padding to protect the hard drive from impacts. </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></div></li>\r\n<li><div><strong>Water Resistance:</strong><p>Some pouches are designed with water-resistant materials to prevent damage from spills or wet conditions. </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></div></li>\r\n<li><div><strong>Storage Compartments:</strong><p>Features like zippered pockets, mesh compartments, and straps are common for organizing accessories like USB cables, memory cards, and other small items. </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></div></li>\r\n<li><div><strong>Secure Closure:</strong><p>Many pouches utilize zippers or magnetic closures to keep the hard drive safely inside. </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></div></li></ul></div>\r\n<p>Additional Considerations:</p><ul><li><strong>Warranty:</strong> While the pouch itself doesn\\\'t have a warranty from WD, the hard drive it protects will have its own warranty. <div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></li>\r\n<li><strong>Durability:</strong> The specific durability of the pouch will depend on the materials used and the overall construction. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li><li><strong>Style and Design:</strong> Pouch designs can vary in terms of color, style, and overall aesthetics.</li></ul></div></div>',NULL,'standard',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'wd-hard-drive-pouch',NULL,NULL,NULL,0.0000,NULL,2,0,'',0,0,'0000-00-00 00:00:00'),(24,'ST004','SAMSUNG T7 1TB PORTABLE SSD',1,32000.0000,37000.0000,0.0000,'no_image.png',63,NULL,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,50,'samsung-t7-1tb-portable-ssd',NULL,NULL,NULL,0.0000,NULL,7,0,'',0,0,'0000-00-00 00:00:00'),(25,'PSSD001','ADATA SD620 1TB PORTABLE SSD',1,22000.0000,25000.0000,0.0000,'no_image.png',63,NULL,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><ul>\r\n<li><strong>Capacity:</strong> 1TB.</li><li><strong>Transfer Speed:</strong> Up to 520 MB/s.</li><li><strong>Interface:</strong> USB 3.2 Gen 2 (backward compatible with USB 2.0).</li><li><strong>Dimensions:</strong> 80 x 80 x 15.2 mm.</li><li><strong>Weight:</strong> 54.9g.</li><li><strong>Durability:</strong> 1.22m MIL-STD drop resistance.</li><li><strong>Compatibility:</strong> Supports various operating systems (Windows, Mac, Linux, Android).</li><li><strong>Case Material:</strong> Silicone.</li></ul>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,12,'adata-sd620-1tb-portable-ssd',NULL,NULL,NULL,0.0000,NULL,1,0,'',0,0,'0000-00-00 00:00:00'),(26,'PSDD002','ADATA SD620 512GB PORTABLE SSD',1,12000.0000,15000.0000,0.0000,'no_image.png',63,NULL,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><ul>\r\n<li><strong>Capacity:</strong> 512GB</li><li><strong>Interface:</strong> USB 3.2 Gen 2 (10Gbps), backward compatible with USB 2.0</li><li><strong>Read Speed (Max):</strong> 520MB/s</li><li><strong>Write Speed (Max):</strong> 460MB/s</li><li><strong>Dimensions:</strong> 80 x 80 x 15.2mm (L x W x H)</li><li><strong>Weight:</strong> 54.9g</li><li><strong>Colors:</strong> Black, Blue, and Red</li><li><strong>Operating Temperatures:</strong> 5°C to 50°C</li><li><strong>Operating Voltage:</strong> 5V</li><li><strong>Warranty:</strong> 3 years</li><li><strong>Shock Resistance:</strong> 1.22m MIL-STD drop</li></ul>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,41,'adata-sd620-512gb-portable-ssd',NULL,NULL,NULL,0.0000,NULL,3,0,'',0,0,'0000-00-00 00:00:00'),(27,'PSSD003','ADATA SE760 512GB SUPER FAST PORTABLE SSD',1,15500.0000,18000.0000,0.0000,'no_image.png',63,NULL,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><p>Key Features:</p><ul><li><strong>Capacity:</strong> 512GB</li><li><strong>Interface:</strong> USB 3.2 Gen 2 Type-C (backward compatible with USB 2.0)</li><li><strong>Read Speed:</strong> Up to 1000 MB/s</li><li><strong>Write Speed:</strong> Up to 800 MB/s</li><li><strong>Compatibility:</strong> Windows, Mac OS, Linux, Android</li><li><strong>Dimensions:</strong> 122.2 x 44 x 14mm (L x W x H)</li><li><strong>Weight:</strong> 95g <div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></li></ul><p>Additional Details:</p><ul><li>The SE760 is a solid state drive (SSD), meaning it has no moving parts and offers faster data transfer speeds and better durability compared to traditional hard disk drives (HDDs). <div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></li>\r\n<li>It is designed to be portable and suitable for various devices, including laptops, gaming consoles, and desktops. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li>\r\n<li>The drive is available in black and titanium gray colors. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li><li>A limited 3-year warranty is included.</li></ul>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,41,'adata-se760-512gb-super-fast-portable-ssd',NULL,NULL,NULL,0.0000,NULL,1,0,'',0,0,'0000-00-00 00:00:00'),(28,'ST015','WD MYPASSPORT ENCLOSURE',1,1200.0000,2300.0000,0.0000,'386b6bb68b8d70d534464620e1067366.jpg',67,61,'','','','','','',0.0000,NULL,1,'',NULL,'code25',NULL,'<p>06 MONTHS WARRANTY</p><p>The My Passport hard drive enclosure is made of a matt plastic casing. It is designed to be compact and portable, with dimensions varying based on capacity. The enclosure is <mark>USB 3.0 and USB 2.0 compatible, and supports hard drives up to 1TB</mark>. </p><p>&lt;svg&gt;&lt;/svg&gt;</p><p>Enclosure Details:</p><ul><li><strong>Material:</strong> Matt plastic casing. \r\n<p>&lt;svg&gt;&lt;/svg&gt;</p></li><li><strong>Interface:</strong> USB 3.0 and USB 2.0 compatible. \r\n<p>&lt;svg&gt;&lt;/svg&gt;</p></li><li><strong>Compatibility:</strong> Supports 2.5-inch laptop hard drives or SSDs up to 1TB. \r\n<p>&lt;svg&gt;&lt;/svg&gt;</p></li><li><strong>Dimensions:</strong> Varies by model and capacity (e.g., 4.22\\\" x 2.95\\\" x 0.81\\\" for 6TB). \r\n<p>&lt;svg&gt;&lt;/svg&gt;</p></li><li><strong>Weight:</strong> Varies by model and capacity (e.g., 0.46 lb for 6TB, 0.21 kg). \r\n<p>&lt;svg&gt;&lt;/svg&gt;</p></li><li><strong>Functionality:</strong> Converts a laptop hard drive or SSD into an external hard drive. \r\n<p>&lt;svg&gt;&lt;/svg&gt;</p></li><li><strong>Additional Features:</strong> Designed for style and protection, offering high-capacity storage in a sleek design.</li></ul>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'wd-mypassport-enclosure',NULL,NULL,NULL,0.0000,NULL,16,0,'',0,0,'0000-00-00 00:00:00'),(29,'UST016','PORTABLE NVME ENCLOSURE',1,2300.0000,3500.0000,0.0000,'3187946e457da116635c4a3080c40a06.jpeg',61,NULL,'','','','','','',0.0000,NULL,1,'',NULL,'code25',NULL,'<p>06 MONTHS WARRANTY</p><p>A portable M.2 NVMe SSD enclosure is designed to allow users to connect an M.2 NVMe SSD to a computer via USB, typically for external storage or to use the SSD as a boot drive. The enclosure generally <mark>supports M.2 SSDs with sizes of 2230, 2242, 2260, and 2280</mark>. </p>\r\n<div>&lt;svg&gt;&lt;/svg&gt;<p>Here\\\'s a breakdown of the specifications:</p>\r\n<ul>\r\n<li>\r\n<div><div><strong>Compatibility:</strong><p>The enclosure is designed to work with M.2 NVMe SSDs, specifically those in the 2230, 2242, 2260, and 2280 form factors. </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></div></div></li><li><strong>Interface:</strong>\r\n<p>Typically, the enclosure uses a USB-C connection (USB 3.1 Gen 2 or USB 3.2 Gen 2) for data transfer, allowing for high speeds. </p><div><div>&lt;svg&gt;&lt;/svg&gt;\r\n</div></div></li><li><strong>Data Transfer Speed:</strong>\r\n<p>Enclosures often offer data transfer rates of 10Gbps or 40Gbps (depending on the specific model). </p><div><div>&lt;svg&gt;&lt;/svg&gt;\r\n</div></div></li><li><strong>Capacity:</strong>\r\n<p>The enclosure is compatible with M.2 NVMe SSDs with capacities ranging from 128GB to 4TB or higher. </p><div><div>&lt;svg&gt;&lt;/svg&gt;\r\n</div></div></li><li><strong>Operating Systems:</strong>\r\n<p>Enclosures generally support Windows, macOS, and Linux operating systems. </p><div><div>&lt;svg&gt;&lt;/svg&gt;\r\n</div></div></li><li><strong>Portability:</strong>\r\n<p>They are typically compact and lightweight, making them convenient for travel and portability. </p><div><div>&lt;svg&gt;&lt;/svg&gt;\r\n</div></div></li><li><strong>Materials:</strong>\r\n<p>Enclosures often feature an aluminum housing for heat dissipation and durability. </p><div><div>&lt;svg&gt;&lt;/svg&gt;\r\n</div></div></li><li><strong>Features:</strong>\r\n<p>Some enclosures include features like tool-free assembly, silicone pins for secure SSD placement, and braided USB-C cables.</p></li></ul></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'portable-nvme-enclosure',NULL,NULL,NULL,0.0000,NULL,3,0,'',0,0,'0000-00-00 00:00:00'),(30,'SD005','SANDISK 128GB MICRO SD',1,2600.0000,3200.0000,0.0000,'no_image.png',59,NULL,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,103,'sandisk-128gb-micro-sd',NULL,NULL,NULL,0.0000,NULL,1,0,'',0,0,'0000-00-00 00:00:00'),(31,'PEN001','KINGSTON 256GB USB 3.2 PEN DRIVE',1,5800.0000,7500.0000,0.0000,'fda1dd11ca740b51239c22b43e66fe72.jpeg',60,NULL,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,18,'kingston-256gb-usb-32-pen-drive',NULL,NULL,NULL,0.0000,NULL,4,0,'',0,0,'0000-00-00 00:00:00'),(32,'PEN005','KINGSTON 128GB USB 3.2 PEN DRIVE',1,3500.0000,5500.0000,0.0000,'9d331c76f8d8db4384946f068d13739c.jpeg',80,60,'','','','','','',4.0000,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><p>The Kingston DataTraveler Exodia USB 3.2 Gen 1 128GB pen drive has a capacity of 128GB, uses the USB 3.2 Gen 1 standard, and is backward compatible with USB 2.0. It is available in a 128GB capacity and has <mark>dimensions of 67.3mm x 21.04mm x 10.14mm</mark>. It weighs 11g and has operating temperatures between 0°C and 60°C and storage temperatures between -20°C and 85°C. It is compatible with Windows 11, 10, macOS (v. 10.15.x +), Linux (v. 4.4 +), and Chrome OS. </p><div>Key Specifications:<ul>\r\n<li><strong>Capacity:</strong> 128GB</li><li><strong>Interface:</strong> USB 3.2 Gen 1 compliant</li><li><strong>Dimensions:</strong> 67.3mm x 21.04mm x 10.14mm</li><li><strong>Weight:</strong> 11g</li><li><strong>Operating Temperature:</strong> 0°C~60°C</li><li><strong>Storage Temperature:</strong> -20°C~85°C</li><li><strong>Warranty:</strong> 5-year warranty</li><li><strong>Compatibility:</strong> Windows® 11, 10, macOS® (v.10.15.x +), Linux (v. 4.4 +), Chrome OS™</li></ul></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,18,'kingston-128gb-usb-32-pen-drive',NULL,NULL,NULL,0.0000,NULL,2,0,'',0,0,'0000-00-00 00:00:00'),(33,'PEN002','KINGSTON 64GB USB 3.2 PEN DRIVE',1,1500.0000,3900.0000,0.0000,'73771d50a93b9a9f976fded56593d999.jpg',80,60,'','','','','','',4.0000,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><p>The Kingston 64GB USB 3.2 pen drive, specifically the DataTraveler Exodia series, offers <mark>USB 3.2 Gen 1 speeds for data transfer and storage</mark>. It supports a wide range of operating systems, including Windows, macOS, Linux, and Chrome OS, and comes with a 5-year warranty and free technical support. The pen drive is known for its practical design and fashionable colors. </p><div><div><br><p>Key Features and Specifications:</p><ul>\r\n<li><strong>Capacity:</strong> 64GB</li><li><strong>Interface:</strong> USB 3.2 Gen 1</li><li><strong>Speed:</strong> Up to 200MB/s read, 60MB/s write</li><li><strong>Compatibility:</strong> Windows 8 and later, macOS 10.10.x and later, Linux 2.6 and later, Chrome OS</li><li><strong>Design:</strong> Practical, fashionable, and available in multiple colors</li><li><strong>Loop:</strong> Includes a large loop for easy attachment to key rings</li><li><strong>Protection:</strong> Cap protects the USB plug</li><li><strong>Warranty:</strong> 5-year warranty and free technical support</li><li><strong>Backward Compatibility:</strong> Compatible with existing USB 2.0 ports</li>\r\n<li><strong>Dimensions:</strong> 67.3mm x 21.04mm x 10.14mm \r\n<div></div></li></ul></div><p>Additional Notes:</p><ul><li>The DataTraveler Exodia series is designed for everyday use at work, home, school, or wherever data needs to be taken. <div></div></li><li>Kingston offers other pen drives, like the DataTraveler Kyson, which also utilize USB 3.2 Gen 1 and offer similar features with a metal housing and capless design. \r\n</li><li>The DataTraveler MicroDuo 3c offers a Type-A/C OTG (On-The-Go) flash drive, expanding compatibility with devices that support USB-C.</li></ul></div><p><a href=\\\"\\\\\\\">\r\n</a></p>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'kingston-64gb-usb-32-pen-drive',NULL,NULL,NULL,0.0000,NULL,1,0,'',0,0,'0000-00-00 00:00:00'),(34,'PRINT001','CANON PIXMA G3010 ALL IN ONE WIRELESS INK TANK COLOUR PRINTER',1,54500.0000,63000.0000,0.0000,'c03bd3672d3a0aab56405e861d0ac04d.png',68,NULL,'','','','','','',0.0000,NULL,1,'',NULL,'code25',NULL,'<p>01 YEAR WARRANTY</p><div>\r\n<div>Key Features and Specifications:<ul>\r\n<li><strong>Print, Scan, and Copy:</strong> All-in-one functionality for various tasks.</li><li><strong>Wireless Connectivity:</strong> Allows for easy connection to networks.</li><li><strong>Ink Tank System:</strong> Refillable ink tanks for low running costs.</li><li><strong>Print Speed:</strong> Up to 8.8 ipm (black) and 5.0 ipm (color).</li><li><strong>Print Resolution:</strong> 4800 x 1200 dpi.</li><li><strong>Paper Input Capacity:</strong> A4/Letter plain paper.</li><li><strong>Recommended Monthly Volume:</strong> 150-1500 pages.</li><li><strong>Display:</strong> 1.2-inch LCD (mono).</li><li><strong>Print Head:</strong> Total 1,472 nozzles, with GI-790 ink bottles (black pigment and color dye-based).</li><li><strong>Operating System Compatibility:</strong> Windows 10, 8.1, 7 SP1, and Chrome OS.</li><li><strong>Dimensions:</strong> 445 x 533 x 260 mm (W x D x H).</li><li><strong>Weight:</strong> 6.3 kg.</li><li><strong>Printing Technologies:</strong> Inkjet and InkTank.</li><li><strong>Connectivity:</strong> Wi-Fi, Mopria, and Direct Wireless.</li><li><strong>Mobile Printing:</strong> Does not support mobile printing.</li><li><strong>Scanner Type:</strong> Flatbed scanner.</li><li><strong>Optical Resolution:</strong> 600 x 1200 dpi.</li><li><strong>Maximum Document Size:</strong> A4/Letter (216 x 297mm).</li><li><strong>Copy Speed:</strong> Approximately 2.5 ipm.</li><li><strong>Network Protocol:</strong> TCP/IP.</li><li><strong>Network Type:</strong> IEEE802.11n/g/b.</li><li><strong>Security:</strong> WEP64/128bit, WPA-PSK (TKIP/AES), WPA2-PSK (TKIP/AES).</li><li><strong>Printing Solutions:</strong> Google Cloud Print, Canon Print Service Plug-In (on Android OS), and PIXMA Cloud Link.</li><li><strong>Ink End Sensor:</strong> Dot count.</li><li><strong>Print Head Alignment:</strong> Manual.</li><li><strong>Paper Weight:</strong> 64 - 105 g/m² (Plain Paper), 275 g/m² (Canon specialty paper).</li></ul></div></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'canon-pixma-g3010-all-in-one-wireless-ink-tank-colour-p',NULL,NULL,NULL,0.0000,NULL,3,0,'',0,0,'0000-00-00 00:00:00'),(35,'SD004','REMAX 32GB MICRO SD ',1,1150.0000,1800.0000,0.0000,'259445f5cba00f6877f121bcce96f635.jpeg',59,NULL,'','','','','','',1.0000,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><p>A REMAX 32GB Micro SD card offers a <mark>storage capacity of 32 GB, supports high-speed data transfer of up to 80 MB/s</mark>, and is compatible with various devices like smartphones, tablets, and GPS. It\\\'s designed for HD video shooting and photography, allowing users to store a significant number of photos and videos. </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div><div>\r\n<div>Detailed Specifications:<ul>\r\n<li><strong>Storage Capacity:</strong> 32 GB.</li><li><strong>Data Transfer Speed:</strong> Up to 80 MB/s.</li><li><strong>Compatibility:</strong> Smartphones, tablets, GPS devices, and other devices that support Micro SD cards.</li><li><strong>Class:</strong> Typically Class 10, indicating a minimum sustained write speed of 10 MB/s.</li><li><strong>Other Features:</strong> Supports HD video shooting, can store a large number of photos (e.g., 10,400 5-megapixel photos) and videos (e.g., 1088 minutes of 1080p video).</li><li><strong>Dimensions:</strong> Approximately 11mm x 15mm x 1mm.</li></ul></div></div></div></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,97,'remax-32gb-micro-sd',NULL,NULL,NULL,0.0000,NULL,1,0,'',0,0,'0000-00-00 00:00:00'),(36,'SD003','REMAX 64GB MICRO SD CLASS 10',1,1500.0000,3000.0000,0.0000,'c11354af4a75298c2bb94b613e71b9e8.jpeg',59,NULL,'','','','','','',1.0000,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><p>A REMAX 64GB microSD Class 10 card is a type of memory card that offers <mark>64 gigabytes of storage and meets the Class 10 speed requirements, meaning it guarantees a minimum write speed of 10 MB/s</mark>. These cards are commonly used in smartphones, tablets, and cameras for storing photos, videos, and other data. </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div>\r\n<p>Here\\\'s a more detailed breakdown:</p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div>\r\n<p>Key Features:</p><ul><li><strong>Capacity:</strong> 64GB, allowing for a significant amount of storage. <div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></li>\r\n<li><strong>Class 10:</strong> Guarantees a minimum write speed of 10 MB/s. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li>\r\n<li><strong>MicroSD:</strong> A small, portable memory card format. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li>\r\n<li><strong>UHS-I:</strong> This designation indicates that the card supports Ultra High Speed (UHS) transfer speeds, potentially offering read speeds up to 80 MB/s. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li>\r\n<li><strong>Compatible with various devices:</strong> Smartphones, cameras, tablets, and other devices that use microSD cards. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li></ul></div>\r\n<p>Benefits of a Class 10 microSD Card:</p><ul><li><strong>Faster Data Transfer:</strong> The Class 10 speed rating ensures faster data transfer for photos and videos, especially when recording HD or Full HD video. <div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div></div></div></li>\r\n<li><strong>Suitable for High-Demand Applications:</strong> Good for devices where you need to quickly save and retrieve large files. \r\n<div>&lt;svg&gt;&lt;/svg&gt;</div></li><li><strong>Reliable Performance:</strong> Class 10 cards are generally considered reliable and durable for everyday use.</li></ul></div></div></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'remax-64gb-micro-sd-class-10',NULL,NULL,NULL,0.0000,NULL,6,0,'',0,0,'0000-00-00 00:00:00'),(37,'URAM002','TRANSCEND DDR4 8GB 3200MHZ LAPTOP RAM',1,3300.0000,7000.0000,0.0000,'3b6c9fa37f73bf48a1973b2b3c262bf6.jpeg',62,NULL,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><p>The Transcend DDR4 8GB 3200MHz Laptop RAM is a high-speed, energy-efficient memory module for laptops. It offers a <mark>3200MHz speed, CL22 latency, and operates at 1.2V</mark>, providing a balance of performance and efficiency. The SO-DIMM form factor makes it compatible with most laptops, and it is built with ETT grade chips for reliability. </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div><div>\r\n<div>Key Specifications:<ul>\r\n<li><strong>RAM Type:</strong> DDR4</li><li><strong>DIMM Type:</strong> Unbuffered SO-DIMM</li><li><strong>Speed:</strong> 3200 MHz</li><li><strong>CAS Latency:</strong> CL22</li><li><strong>Capacity:</strong> 8 GB</li><li><strong>Rank x Org:</strong> 1Rx8</li><li><strong>Voltage:</strong> 1.2V</li><li><strong>Pin Count:</strong> 260 pin</li><li><strong>PCB Height:</strong> 1.18 inches</li><li><strong>Operating Temperature:</strong> 0°C (32°F) ~ 85°C (185°F)</li><li><strong>Warranty:</strong> Transcend warranty policy (at Service Centre)</li></ul></div></div></div></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,22,'transcend-ddr4-8gb-3200mhz-laptop-ram',NULL,NULL,NULL,0.0000,NULL,82,0,'',0,0,'0000-00-00 00:00:00'),(38,'RAM003','TRANSCEND DDR5 16GB 5600MHZ LAPTOP RAM',1,14200.0000,74500.0000,0.0000,'d4863cdb5caa76759b0ba3f7beac3a5f.jpeg',62,NULL,'','','','','','',0.0000,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><p>The Transcend 16GB DDR5 5600MHz laptop RAM module is designed for use in laptops and features the following specifications: </p>\r\n<div><br><ul><li><strong>RAM Type:</strong> DDR5</li><li><strong>DIMM Type:</strong> Unbuffered SO-DIMM</li><li><strong>Speed:</strong> 5600 MHz</li><li><strong>CAS Latency:</strong> CL46</li><li><strong>Capacity:</strong> 16 GB</li><li><strong>Voltage:</strong> 1.1V</li><li><strong>Pin Count:</strong> 262</li><li><strong>Rank x Org:</strong> 1Rx8</li><li><strong>Component Composition:</strong> (2Gx8)x8</li><li><strong>PCB Height:</strong> 1.18 inches</li><li><strong>Operating Temperature:</strong> 0°C (32°F) ~ 85°C (185°F)</li></ul></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,22,'transcend-ddr5-16gb-5600mhz-laptop-ram',NULL,NULL,NULL,0.0000,NULL,1,0,'',0,0,'0000-00-00 00:00:00'),(39,'RAM002','CRUCIAL DDR4 8GB 3200MHZ LAPTOP RAM',1,4500.0000,7000.0000,0.0000,'65acb005dd6f61dd9650379599ddc17f.jpeg',62,NULL,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><p>The Crucial 8GB DDR4 3200MHz laptop RAM is a 260-pin SODIMM module designed for laptops. It offers a <mark>memory speed of 3200 MHz, a CAS latency of CL22, and operates at a voltage of 1.2V</mark>. The module is single-ranked, unbuffered, and non-ECC. It is also PC4-25600. </p><div><div><div><div>&lt;svg&gt;&lt;/svg&gt;</div></div><div>\r\n<div>Key Specifications:<ul>\r\n<li><strong>Technology:</strong> DDR4</li><li><strong>Speed:</strong> 3200 MHz</li><li><strong>Density:</strong> 8 GB</li><li><strong>Module Type:</strong> SODIMM</li><li><strong>CAS Latency:</strong> CL22</li><li><strong>Voltage:</strong> 1.2V</li><li><strong>PC Speed:</strong> PC4-25600</li><li><strong>Form Factor:</strong> SODIMM</li><li><strong>Pin Count:</strong> 260-pin</li><li><strong>Rank:</strong> Single Ranked</li><li><strong>ECC:</strong> Non-ECC</li><li><strong>DIMM Type:</strong> Unbuffered</li><li><strong>Extended Timings:</strong> 22-22-22</li></ul></div></div></div></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'crucial-ddr4-8gb-3200mhz-laptop-ram',NULL,NULL,NULL,0.0000,NULL,2,0,'',0,0,'0000-00-00 00:00:00'),(40,'VIRUS002','KASPERSKY SECURITY 03 DEVICE',1,3650.0000,5000.0000,0.0000,'50d3dba1a343c9b446ca9d31d535093a.jpeg',71,NULL,'','','','','','',1.0000,NULL,1,'',NULL,'code25',NULL,'',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'kaspersky-security-03-device',NULL,NULL,NULL,0.0000,NULL,4,0,'',0,0,'0000-00-00 00:00:00'),(41,'ST002','ADDLINK S70 512GB NVME',1,10000.0000,12500.0000,0.0000,'6e20438d383c56e4c2f9ca79a80ff89e.jpeg',67,99,'','','','','','',0.0000,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p>\r\n<div><br><div><p>Key Features:</p><ul>\r\n<li><strong>Capacity:</strong> 512GB</li><li><strong>Interface:</strong> NVMe GEN3x4 1.3</li><li><strong>Form Factor:</strong> M.2 2280</li><li><strong>Sequential Read/Write Speed:</strong> 3000/2000 MB/s (for the 512GB model)</li>\r\n<li><strong>Operating Temperature:</strong> 0°C ~ 70°C \r\n</li></ul></div></div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,16,'addlink-s70-512gb-nvme',NULL,NULL,NULL,0.0000,NULL,2,0,'',0,0,'0000-00-00 00:00:00'),(42,'ST003','ADDLINK S70 256GB SSD NVME',1,18750.0000,22000.0000,0.0000,'6881014595926394bd11efd9e06e73b5.jpeg',67,99,'','','','','','',3.0000,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><p>The ADDLink S70 256GB SSD is an NVMe PCIe Gen3x4 drive, offering a <mark>256GB capacity and speeds of up to 3000MB/s read and 1000MB/s write</mark>. It is a M.2 2280 form factor drive, supporting SMART and TRIM commands and features a 5-year or 400 TBW limited warranty. It\\\'s compatible with Intel and AMD platforms. </p><p>&lt;svg&gt;&lt;/svg&gt;\r\n</p><p>Key Features:</p><ul><li><strong>Capacity:</strong> 256GB</li><li><strong>Interface:</strong> PCIe Gen3x4 NVMe 1.3</li><li><strong>Form Factor:</strong> M.2 2280</li><li><strong>Read Speed:</strong> Up to 3000 MB/s</li><li><strong>Write Speed:</strong> Up to 1000 MB/s</li><li><strong>Warranty:</strong> 5-year or 400 TBW limited</li><li><strong>Compatibility:</strong> Intel and AMD platforms</li><li><strong>Features:</strong> SMART, TRIM, LDPC, RAID engine</li></ul>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,16,'addlink-s70-256gb-ssd-nvme',NULL,NULL,NULL,0.0000,NULL,6,0,'',0,0,'0000-00-00 00:00:00'),(43,'COLPD011','ALLUMINIUM LAPTOP STAND',1,800.0000,2000.0000,0.0000,'ae6943e764f5269502b2b4df499bd8d4.png',88,55,'','','','','','',34.0000,NULL,1,'',NULL,'code25',NULL,'',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,0,'alluminium-laptop-stand',NULL,NULL,NULL,0.0000,NULL,2,0,'',0,0,'0000-00-00 00:00:00'),(44,'ST006','LEXAR NS100 256GB SSD',1,6000.0000,19500.0000,0.0000,'99190be693e79173dd17f8c133c21913.jpeg',67,99,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><p>The Lexar NS100 256GB SSD is a <mark>2.5-inch SATA III (6Gb/s) drive with a sequential read speed of up to 550MB/s</mark>. It has a TBW (Terabytes Written) of 128TB and a DWPD (Daily Write Per Day) of 0.46. The SSD weighs 34g and has dimensions of 69.85mm x 100.2mm x 7mm. It\\\'s also shock and vibration resistant.</p><p>Capacity: 256GB<br>Interface: 2.5\\\" SATA III (6Gb/s)<br>Read Speed: Up to 550MB/s<br>Weight: 34g </p><p>Dimensions (L x W x H): 69.85mm x 100.2mm x 7mm (2.75\\\" x 3.94\\\" x 0.28\\\")</p><div>\r\n</div>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,19,'lexar-ns100-256gb-ssd',NULL,NULL,NULL,0.0000,NULL,10,0,'',0,0,'0000-00-00 00:00:00'),(45,'ST011','LEXAR NS100 1TB SSD',1,17500.0000,20000.0000,0.0000,'4e929755ef868da3e09efca04f7f0a1b.jpeg',67,99,'','','','','','',NULL,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><p>Key Features:</p><ul><li><strong>Capacity:</strong> 1TB</li><li><strong>Interface:</strong> SATA III (6Gb/s)</li><li><strong>Form Factor:</strong> 2.5\\\"</li><li><strong>Sequential Read Speed:</strong> Up to 550MB/s</li><li><strong>Dimensions:</strong> 69.85mm x 100.2mm x 7mm</li><li><strong>Weight:</strong> 34g</li><li><strong>Shock Resistance:</strong> 1500G, 0.5ms, Half Sine Wave</li><li><strong>Vibration Resistance:</strong> 10~2000 Hz, 1.5mm, 20 G, 1 Oct/min, 30min/axis (X,Y,Z)</li><li><strong>TBW (Total Bytes Written):</strong> 512TB</li><li><strong>DWPD (Daily Write Per Day):</strong> 0.46</li><li><strong>Operating Temperature:</strong> 0°C to 70°C (32°F to 158°F)</li><li><strong>Storage Temperature:</strong> -40°C to 85°C (-40°F to 185°F)</li></ul>',NULL,'standard',12,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'',NULL,NULL,NULL,NULL,1,1,19,'lexar-ns100-1tb-ssd',NULL,NULL,NULL,0.0000,NULL,3,0,'',0,0,'0000-00-00 00:00:00'),(46,'ST013','LEXAR NS100 128GB SSD',1,5150.0000,8400.0000,0.0000,'ecf3d97eef44e500ee205ee8fc8f6ae4.jpeg',67,99,'','','','','','',27.0000,NULL,1,'',NULL,'code25',NULL,'<p>03 YEARS WARRANTY</p><ul>\r\n<li><strong>Interface:</strong> 2.5-